                dp[i][i][b] = 1

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                c = cost(s[i], s[j])

                for b in range(k + 1):
                    best = max(dp[i + 1][j][b], dp[i][j - 1][b])

                    if c <= b:
                        middle = dp[i + 1][j - 1][b - c] if length > 2 else 0
                        best = max(best, 2 + middle)

